//! `DateTimeZone` and the timezone functions against PHP 8.5.13 (`tests/vectors/timezone.json`, generated by
//! `timezone.gen.php`; regenerate with `crates/twig-date/tests/vectors/regen.sh timezone`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::timezone::{timezone_name_from_abbr, timezone_open};
use twig_date::{DateObject, TimeZoneObject, classes};
use twig_value::{Value, compare, convert};

fn tz_json(o: &twig_value::ObjectRef) -> Json {
    to_json(&Value::Array(
        convert::to_array(&Value::Object(o.clone()), &mut Vec::new()).unwrap(),
    ))
}

#[test]
fn construct_and_open() {
    let v = load("timezone");
    let c = Ctx::new();
    let mut r = Report::new("new DateTimeZone() / timezone_open()");
    for case in v["construct"].as_array().unwrap() {
        let name = bytes(&case[0]);
        let (got, arr) = match TimeZoneObject::construct(&c.ctx, &name) {
            Ok(o) => {
                let n = call(&o, "getName", vec![], &mut Vec::new()).unwrap();
                (str_val(&n), tz_json(&o))
            }
            Err(e) => (exc(&e), Json::Null),
        };
        r.eq(got, s(&case[1]).to_owned(), || format!("{case}"));
        r.eq(arr, case[2].clone(), || format!("(array) {case}"));
        let mut diags = Vec::new();
        let open = match timezone_open(&c.ctx, &name, &mut diags) {
            Ok(Some(o)) => Json::String(str_val(
                &call(&o, "getName", vec![], &mut Vec::new()).unwrap(),
            )),
            Ok(None) => Json::Bool(false),
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(open, case[3].clone(), || format!("timezone_open {case}"));
        r.eq(Json::from(diag_strings(&diags)), case[4].clone(), || {
            format!("diagnostics {case}")
        });
    }
    r.finish();
}

#[test]
fn offsets_locations_transitions() {
    let v = load("timezone");
    let c = Ctx::new();
    let mut r = Report::new("getOffset()/getLocation()/getTransitions()");
    for case in v["offset"].as_array().unwrap() {
        let tz = TimeZoneObject::construct(&c.ctx, s(&case[0]).as_bytes()).unwrap();
        let d = DateObject::construct(
            &c.ctx,
            classes::datetime(),
            format!("@{}", i(&case[1])).as_bytes(),
            None,
        )
        .unwrap();
        let got = call(&tz, "getOffset", vec![Value::Object(d)], &mut Vec::new()).unwrap();
        r.eq(to_json(&got), case[2].clone(), || format!("{case}"));
    }
    for case in v["location"].as_array().unwrap() {
        let tz = TimeZoneObject::construct(&c.ctx, s(&case[0]).as_bytes()).unwrap();
        let got = call(&tz, "getLocation", vec![], &mut Vec::new()).unwrap();
        r.eq(to_json(&got), case[1].clone(), || format!("{case}"));
    }
    for case in v["transitions"].as_array().unwrap() {
        let tz = TimeZoneObject::construct(&c.ctx, s(&case[0]).as_bytes()).unwrap();
        let args = if case[1].is_null() {
            vec![]
        } else {
            vec![Value::Int(i(&case[1])), Value::Int(i(&case[2]))]
        };
        let got = call(&tz, "getTransitions", args, &mut Vec::new()).unwrap();
        r.eq(to_json(&got), case[3].clone(), || {
            format!("{} {} {}", case[0], case[1], case[2])
        });
    }
    r.finish();
}

#[test]
fn identifiers_and_abbreviations() {
    let v = load("timezone");
    let c = Ctx::new();
    let tz = TimeZoneObject::construct(&c.ctx, b"UTC").unwrap();
    let mut r = Report::new("listIdentifiers()/listAbbreviations()/timezone_name_from_abbr()");
    for case in v["identifiers"].as_array().unwrap() {
        let cc = case[1].as_str().map_or(Value::Null, Value::from);
        let got = match call(
            &tz,
            "listIdentifiers",
            vec![Value::Int(i(&case[0])), cc],
            &mut Vec::new(),
        ) {
            Ok(v) => to_json(&v),
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(got, case[2].clone(), || format!("{} {}", case[0], case[1]));
    }
    let got = call(&tz, "listAbbreviations", vec![], &mut Vec::new()).unwrap();
    r.eq(to_json(&got), v["abbreviations"].clone(), || {
        "listAbbreviations()".to_owned()
    });
    for case in v["from_abbr"].as_array().unwrap() {
        let got = timezone_name_from_abbr(&bytes(&case[0]), i(&case[1]), i(&case[2]));
        r.eq(to_json(&got), case[3].clone(), || format!("{case}"));
    }
    r.finish();
}

#[test]
fn comparisons() {
    let v = load("timezone");
    let c = Ctx::new();
    let mut r = Report::new("DateTimeZone comparisons");
    for case in v["compare"].as_array().unwrap() {
        let a = Value::Object(TimeZoneObject::construct(&c.ctx, s(&case[0]).as_bytes()).unwrap());
        let b = Value::Object(TimeZoneObject::construct(&c.ctx, s(&case[1]).as_bytes()).unwrap());
        let eq = match compare::equals(&a, &b, &mut Vec::new()) {
            Ok(x) => Json::Bool(x),
            Err(e) => Json::String(exc(&e)),
        };
        let lt = match compare::less(&a, &b, &mut Vec::new()) {
            Ok(x) => Json::Bool(x),
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(eq, case[2].clone(), || format!("== {case}"));
        r.eq(lt, case[3].clone(), || format!("< {case}"));
    }
    r.finish();
}
